"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/facet-filter.css";
import { FunnelSimple, X } from "@phosphor-icons/react";
import { cn } from "../../lib/cn";
import { Button } from "./button";
import {
  Menu,
  MenuCheckboxItem,
  MenuContent,
  MenuItem,
  MenuLabel,
  MenuSeparator,
  MenuTrigger,
} from "./menu";

export type FacetFilterOption = {
  value: string;
  label: string;
  count?: number;
  disabled?: boolean;
};

export type FacetFilterProps = {
  label: string;
  options: readonly FacetFilterOption[];
  values: readonly string[];
  onValuesChange: (values: readonly string[]) => void;
  className?: string;
};

export function FacetFilter({ label, options, values, onValuesChange, className }: FacetFilterProps) {
  const selected = new Set(values);
  const toggle = (value: string, checked: boolean) => {
    const next = checked
      ? [...values.filter((item) => item !== value), value]
      : values.filter((item) => item !== value);
    onValuesChange(next);
  };

  return (
    <span className={cn("whatiuse-facet-filter", className)}>
      <Menu>
        <MenuTrigger
          render={(
            <Button
              size="small"
              variant={values.length > 0 ? "secondary" : "ghost"}
              leadingIcon={<FunnelSimple />}
              aria-label={`${label}: ${values.length > 0 ? `${values.length} selected` : "Any"}`}
            />
          )}
        >
          <span className="whatiuse-facet-filter__trigger-content">
            <span>{label}</span>
            {values.length > 0 && <span className="whatiuse-facet-filter__count" aria-hidden="true">{values.length}</span>}
          </span>
        </MenuTrigger>
        <MenuContent className="whatiuse-facet-filter__menu" align="start">
          <MenuLabel>{label}</MenuLabel>
          {options.map((option) => (
            <MenuCheckboxItem
              key={option.value}
              checked={selected.has(option.value)}
              disabled={option.disabled}
              closeOnClick={false}
              onCheckedChange={(checked) => toggle(option.value, checked)}
            >
              <span className="whatiuse-facet-filter__option">
                <span>{option.label}</span>
                {typeof option.count === "number" && <small>{option.count}</small>}
              </span>
            </MenuCheckboxItem>
          ))}
          {values.length > 0 && (
            <>
              <MenuSeparator />
              <MenuItem onClick={() => onValuesChange([])}>
                <X aria-hidden="true" />Clear {label.toLocaleLowerCase()}
              </MenuItem>
            </>
          )}
        </MenuContent>
      </Menu>
    </span>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-facet-filter {
  display: inline-flex;
  min-width: 0;
  vertical-align: middle;
}

.whatiuse-facet-filter__count {
  display: grid;
  min-width: 16px;
  height: 16px;
  place-items: center;
  flex: 0 0 auto;
  padding-inline: 4px;
  border-radius: 999px;
  background: var(--whatiuse-bg-subtle);
  color: var(--whatiuse-fg-muted);
  font-size: 10px;
  font-variant-numeric: tabular-nums;
  line-height: 1;
}

.whatiuse-facet-filter__trigger-content {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
}

.whatiuse-facet-filter__trigger-content > span:first-child {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.whatiuse-facet-filter__menu { min-width: 208px; }

.whatiuse-facet-filter__option {
  display: grid;
  min-width: 0;
  flex: 1;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 14px;
}

.whatiuse-facet-filter__option > span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.whatiuse-facet-filter__option small {
  color: var(--whatiuse-fg-subtle);
  font-size: var(--whatiuse-type-metadata);
  font-variant-numeric: tabular-nums;
}
}
